# TCC pattern: coordinator orchestrates three phases

def tcc_transfer(from_account: str, to_account: str, amount: float) -> bool:
    # Phase 1: Try — reserve resources on both services
    txn_id = generate_txn_id()
    try_a = account_service.try_debit(txn_id, from_account, amount)
    try_b = account_service.try_credit(txn_id, to_account, amount)

    if try_a and try_b:
        # Phase 2: Confirm — commit both reservations
        account_service.confirm_debit(txn_id, from_account)
        account_service.confirm_credit(txn_id, to_account)
        return True
    else:
        # Phase 3: Cancel — release both reservations
        if try_a: account_service.cancel_debit(txn_id, from_account)
        if try_b: account_service.cancel_credit(txn_id, to_account)
        return False

