# Simplified log-structured storage: always append, never overwrite
class LogStructuredStore:
    def __init__(self, path):
        self.log = open(path, 'ab+')
        self.index = {}  # key -> byte offset of latest value

    def set(self, key: str, value: str) -> None:
        offset = self.log.tell()
        record = f"{key}:{value}\n".encode()
        self.log.write(record)
        self.index[key] = offset  # always points to latest

    def get(self, key: str) -> str | None:
        if key not in self.index:
            return None
        self.log.seek(self.index[key])
        line = self.log.readline().decode()
        return line.split(':', 1)[1].rstrip()

